import{_ as l,a0 as o,w as r,s as d,ao as t,I as e,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"BASIC 與 FORTRAN 77：比較過去的編程語言 | LCTT x X-CMD","titleTemplate":false,"description":"BASIC 與 FORTRAN 77：比較過去的編程語言 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"BASIC 與 FORTRAN 77：比較過去的編程語言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"BASIC 與 FORTRAN 77：比較過去的編程語言 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230405.3 ⭐️⭐️ BASIC vs. FORTRAN 77 Comparing programming blasts from the past","title":"BASIC 與 FORTRAN 77：比較過去的編程語言","tag":"202306","desc":""},"relativePath":"202306/20230405.3 ⭐️⭐️ BASIC vs. FORTRAN 77 Comparing programming blasts from the past.md","filePath":"[post].md"}'),c={name:"202306/20230405.3 ⭐️⭐️ BASIC vs. FORTRAN 77 Comparing programming blasts from the past.md"};function g(u,s,A,C,h,b){const n=o("Link");return r(),d("div",null,[s[28]||(s[28]=t('<h1 id="basic-與-fortran-77-比較過去的編程語言" tabindex="-1">BASIC 與 FORTRAN 77：比較過去的編程語言 <a class="header-anchor" href="#basic-與-fortran-77-比較過去的編程語言" aria-label="Permalink to “BASIC 與 FORTRAN 77：比較過去的編程語言”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/11/110557i6ef2ep92petw2d1.jpg" alt=""></p><blockquote><p>我通過編寫一個示例程序來探索 BASIC 和 FORTRAN 77 中的 FOR 循環，以將數字列表從 1 加到 10。</p></blockquote><p>如果你和我一樣，在 20 世紀七八十年代使用計算機長大，你可能學過一種常見的個人計算機編程語言，名為 BASIC（全稱是 “<ruby>初學者的通用符號指令代碼<rt>Beginner&#39;s All-purpose Symbolic Instruction Code</rt></ruby>”）。那個時期，包括 TRS-80、Apple II 和 IBM PC 在內的每台個人計算機都可以找到 BASIC 實現。當時，我是一個自學的 BASIC 程序員，在嘗試了 Apple II 上的 AppleSoft BASIC 後，轉向 IBM PC 上的 GW-BASIC，後來在 DOS 上學習了 QuickBASIC。</p><p>但是曾經，一種在科學編程領域受歡迎的語言是 FORTRAN（即 “<ruby>公式翻譯<rt>FORmula TRANslation</rt></ruby>”）。儘管在 1990 年對該語言進行的規範以後，該名稱更常見的風格是 “Fortran”。</p><p>當我在 1990 年代初作為大學本科物理學生學習物理學時，我利用自己在 BASIC 上的經驗學習了 FORTRAN 77。那時我意識到 BASIC 許多概念都來源於 FORTRAN。當然，FORTRAN 和 BASIC 在很多其他方面也存在差異，但我發現瞭解一點 BASIC 可以幫助我快速學習 FORTRAN 編程。</p><p>我想通過使用兩種語言編寫相同的程序，展示它們之間的一些相似之處。通過編寫一個示例程序來探索 BASIC 和 FORTRAN 77 中的 <code>FOR</code> 循環，這個程序將把 1 到 10 之間的數字相加。</p><h3 id="bywater-basic" tabindex="-1">Bywater BASIC <a class="header-anchor" href="#bywater-basic" aria-label="Permalink to “Bywater BASIC”">​</a></h3>',8)),e("p",null,[s[1]||(s[1]=a("BASIC 存在許多種不同的版本，這取決於你的計算機，但該語言總體保持不變。我喜歡的一種 BASIC 版本是 ",-1)),i(n,{href:"https://sourceforge.net/projects/bwbasic/"},{default:p(()=>[...s[0]||(s[0]=[a("Bywater BASIC",-1)])]),_:1}),s[2]||(s[2]=a("，這是一種開源的 BASIC 實現，適用於包括 Linux 和 DOS 在內的不同平台。",-1))]),e("p",null,[s[4]||(s[4]=a("要在 FreeDOS 上使用 Bywater BASIC，你必須首先從 FreeDOS 1.3 Bonus CD 中 ",-1)),i(n,{href:"https://opensource.com/article/21/6/freedos-package-manager"},{default:p(()=>[...s[3]||(s[3]=[a("安裝該軟件包",-1)])]),_:1}),s[5]||(s[5]=a("。然後進入 ",-1)),s[6]||(s[6]=e("code",null,"C:",-1)),s[7]||(s[7]=a(" 目錄並輸入 ",-1)),s[8]||(s[8]=e("code",null,"bwbasic",-1)),s[9]||(s[9]=a(" 命令，這將啓動 BASIC 解釋器。你可以在這個提示符下輸入程序：",-1))]),s[29]||(s[29]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bwBASIC:</span></span></code></pre></div><p>Bywater BASIC 使用較早的 BASIC 編程標準，需要你在每個程序指令上編寫一個行號。將行號視為索引。你可以使用行號輕鬆地引用程序中的任何指令。當你將程序鍵入 Bywater BASIC 解釋器時，請在每個指令前添加行號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bwBASIC: 10 print &quot;Add the numbers from 1 to 10 ...&quot;</span></span>
<span class="line"><span>bwBASIC: 20 sum = 0</span></span>
<span class="line"><span>bwBASIC: 30 for i = 1 to 10</span></span>
<span class="line"><span>bwBASIC: 40 sum = sum + i</span></span>
<span class="line"><span>bwBASIC: 50 next i</span></span>
<span class="line"><span>bwBASIC: 60 print sum</span></span>
<span class="line"><span>bwBASIC: 70 end</span></span></code></pre></div><p>可以使用 <code>list</code> 命令查看你已經輸入到解釋器中的程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bwBASIC: list</span></span>
<span class="line"><span>10 print &quot;Add the numbers from 1 to 10 ...&quot;</span></span>
<span class="line"><span>20 sum = 0</span></span>
<span class="line"><span>30 for i = 1 to 10</span></span>
<span class="line"><span>40 sum = sum + i</span></span>
<span class="line"><span>50 next i</span></span>
<span class="line"><span>60 print sum</span></span>
<span class="line"><span>70 end</span></span></code></pre></div><p>這個簡短的程序演示了 BASIC 中的 <code>FOR</code> 循環。 <code>FOR</code> 是任何編程語言中最基本的循環構造，允許你迭代一組值。在 Bywater BASIC 中，<code>FOR</code> 循環的一般語法看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FOR 變量 = 起始值 TO 終止值</span></span></code></pre></div><p>在這個示例程序中，指令 <code>for i = 1 to 10</code> 開始一個循環，迭代值為 1 到 10。在每個循環中，變量 <code>i</code> 被設置為新值。</p><p>在 BASIC 中，所有到 <code>next</code> 指令前的指令都將作為 <code>FOR</code> 循環的一部分執行。因為你可以將一個 <code>FOR</code> 循環放入另一個 <code>FOR</code> 循環中，Bywater BASIC 使用語法 <code>NEXT 變量</code> 來指定要迭代的循環變量。</p><p>在提示符下鍵入 <code>run</code> 來執行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bwBASIC: run</span></span>
<span class="line"><span>Add the numbers from 1 to 10 ...</span></span>
<span class="line"><span>55</span></span></code></pre></div><p>Bywater BASIC 被稱為 BASIC 解釋器，因為只能從 Bywater BASIC 環境中運行程序。這意味着解釋器會處理與操作系統的交互的所有繁重工作，因此你的程序不需要自己完成這個工作。 這樣做的代價是，程序在解釋環境中運行會比它作為編譯程序運行慢一些。</p><h3 id="freebasic" tabindex="-1">FreeBASIC <a class="header-anchor" href="#freebasic" aria-label="Permalink to “FreeBASIC”">​</a></h3>`,13)),e("p",null,[s[11]||(s[11]=a("另一個流行的 BASIC 實現是 ",-1)),i(n,{href:"https://www.freebasic.net/"},{default:p(()=>[...s[10]||(s[10]=[a("FreeBASIC",-1)])]),_:1}),s[12]||(s[12]=a("，這是一個開源的 BASIC 編譯器，適用於多個平台，包括 Linux 和 DOS。要使用 FreeBASIC，你需要從 FreeDOS 1.3 Bonus CD 安裝 FreeBASIC 包，然後進入 ",-1)),s[13]||(s[13]=e("code",null,"C:",-1)),s[14]||(s[14]=a(" 目錄，你會在這裏找到 FreeBASIC 程序。",-1))]),s[30]||(s[30]=t(`<p>FreeBASIC 是一個編譯器，因此你首先需要創建一個包含程序指令的源文件，然後使用源代碼運行編譯器以創建一個可運行的程序。我編寫了一個類似於“將 1 到 10 的數字相加”的程序版本，將其保存為 BASIC 文件，並命名為 <code>sum.bas</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dim sum as integer</span></span>
<span class="line"><span>dim i as integer</span></span>
<span class="line"><span>print &quot;Add the numbers from 1 to 10 ...&quot;</span></span>
<span class="line"><span>sum = 0</span></span>
<span class="line"><span>for i = 1 to 10</span></span>
<span class="line"><span>sum = sum + i</span></span>
<span class="line"><span>next</span></span>
<span class="line"><span>print sum</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>如果你將這段代碼與 Bywater BASIC 版本的程序進行比較，你可能會注意到 FreeBASIC 不需要行號。FreeBASIC 實現了一種更現代的 BASIC 版本，使得編寫程序時不需要跟蹤行號更容易。</p><p>另一個主要的區別是你必須在源代碼中定義或聲明變量。使用 <code>DIM</code> 指令在 FreeBASIC 中聲明變量，例如 <code>dim sum as integer</code>，以定義一個名為 <code>sum</code> 的整數變量。</p><p>現在可以在命令列上使用 <code>fbc</code> 編譯 BASIC 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\DEVEL\\FBC&gt; fbc sum.bas</span></span></code></pre></div><p>如果你的代碼沒有任何錯誤，編譯器將生成一個可以運行的程序。例如，我的程序現在稱為 <code>sum</code>。運行我的程序將從 1 加到 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\DEVEL\\FBC&gt; sum</span></span>
<span class="line"><span>Add the numbers from 1 to 10 ...</span></span>
<span class="line"><span>55</span></span></code></pre></div><h3 id="fortran-77" tabindex="-1">FORTRAN 77 <a class="header-anchor" href="#fortran-77" aria-label="Permalink to “FORTRAN 77”">​</a></h3><p>FORTRAN 編程語言類似於舊式和現代 BASIC 之間的混合體。FORTRAN 比 BASIC 更早出現，而 BASIC 顯然從 FORTRAN 中汲取靈感，就像後來的 FORTRAN 版本從 BASIC 中獲得啓示一樣。你可以將 FORTRAN 程序以源代碼的形式寫成文件，但並不需要在每個地方使用行號。但是，FORTRAN 77 在某些指令中使用行號（稱為標籤），包括 <code>FOR</code> 循環。在 FORTRAN 77 中，<code>FOR</code> 實際上被稱為 <code>DO</code> 循環，它執行相同的功能並具有幾乎相同的用法。</p><p>在 FORTRAN 77 中，<code>DO</code> 循環的語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DO 行號 變量 = 起始值, 終止值</span></span></code></pre></div><p>這種情況是需要行號來指示 <code>DO</code> 循環結束位置的一種情況。你在 BASIC 中使用了 <code>NEXT</code> 指令，但 FORTRAN 需要一個行標籤。通常，該行是一個 <code>CONTINUE</code> 指令。</p><p>查看這個示例 FORTRAN 程序，瞭解如何使用 <code>DO</code> 循環來循環一組數字。我將此源文件保存為 <code>sum.f</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PROGRAM MAIN</span></span>
<span class="line"><span>      INTEGER SUM,I</span></span>
<span class="line"><span>      PRINT *, &#39;ADD THE NUMBERS FROM 1 TO 10 ...&#39;</span></span>
<span class="line"><span>      SUM = 0</span></span>
<span class="line"><span>      DO 10 I = 1, 10</span></span>
<span class="line"><span>        SUM = SUM + I</span></span>
<span class="line"><span>   10 CONTINUE</span></span>
<span class="line"><span>      PRINT *, SUM</span></span>
<span class="line"><span>      END</span></span></code></pre></div><p>在 FORTRAN 中，每個程序都需要以 <code>PROGRAM</code> 指令開始，並指定程序名稱。你可能會將此程序命名為 <code>SUM</code>，但隨後在程序中不能使用變量 <code>SUM</code>。當我學習 FORTRAN 時，我從 C 編程中借鑑了一些東西，並以 <code>PROGRAM MAIN</code> 開始了我的所有 FORTRAN 程序，做法類似於 C 程序中的 <code>main()</code> 函數，因為我不太可能使用名為 <code>MAIN</code> 的變量。</p><p>FORTRAN 中的 <code>DO</code> 循環類似於 BASIC 中的 <code>FOR</code> 循環。它迭代從 1 到 10 的值。變量 <code>I</code> 在每次循環中獲取新值。這樣可以將 1 到 10 的每個數字相加，並在完成時打印總和。</p><p>你可以在每個平台上找到適合的 FORTRAN 編譯器，包括 Linux 和 DOS。FreeDOS 1.3 的 Bonus CD 中包括 OpenWatcom FORTRAN 編譯器。在 Linux 上，你可能需要安裝一個包來安裝 GNU Fortran 支持（在 GNU 編譯器集合（GCC）中）。在 Fedora Linux 上，你可以使用以下命令添加 GNU Fortran 支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gcc-gfortran</span></span></code></pre></div><p>然後你可以使用以下命令編譯 <code>sum.f</code> 並運行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gfortran -o sum sum.f</span></span>
<span class="line"><span>$ ./sum</span></span>
<span class="line"><span>ADD THE NUMBERS FROM 1 TO 10 ...</span></span>
<span class="line"><span>55</span></span></code></pre></div><h3 id="一點不同之處" tabindex="-1">一點不同之處 <a class="header-anchor" href="#一點不同之處" aria-label="Permalink to “一點不同之處”">​</a></h3><p>我發現 FORTRAN 和 BASIC 非常相似，但也存在一些不同之處。這些語言的核心是不同的，但如果你瞭解一些 BASIC，你可以學習 FORTRAN，同樣，如果你瞭解一些 FORTRAN，你也可以學習 BASIC。</p><p>如果你想探索這兩種語言，有幾點需要注意：</p><ul><li><strong>FORTRAN 77 使用全大寫</strong>，但後來的 FORTRAN 版本允許大小寫混用，只要對變量、函數和子程序使用相同的大小寫。大多數 BASIC 實現都不區分大小寫，這意味着你可以自由地混合大小寫字母。</li><li><strong>有許多不同版本的 BASIC</strong>，但它們通常做同樣的事情。如果你學會了一種 BASIC 實現方式，很容易學會另一種。注意 BASIC 解釋器或編譯器的警告或錯誤信息，查閲手冊瞭解差異。</li><li><strong>某些 BASIC 實現需要使用行號</strong>，例如 Bywater BASIC 和 GW-BASIC。更現代的 BASIC 版本允許你編寫不使用行號的程序。FreeBASIC 需要使用 <code>-lang</code> 廢棄選項編譯帶有行號的程序。</li></ul><p><em>（題圖：MJ/dba28597-dd62-4ffe-bb4a-e38874a65239）</em></p><hr>`,27)),e("p",null,[s[16]||(s[16]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/23/4/basic-vs-fortran-77"},{default:p(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/23/4/basic-vs-fortran-77",-1)])]),_:1})]),e("p",null,[s[20]||(s[20]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/jim-hall"},{default:p(()=>[...s[17]||(s[17]=[a("Jim Hall",-1)])]),_:1}),s[21]||(s[21]=a(" 選題：",-1)),i(n,{href:"https://github.com/lkxed/"},{default:p(()=>[...s[18]||(s[18]=[a("lkxed",-1)])]),_:1}),s[22]||(s[22]=a(" 譯者：ChatGPT 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[25]||(s[25]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[23]||(s[23]=[a("LCTT",-1)])]),_:1}),s[26]||(s[26]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...s[24]||(s[24]=[a("Linux中國",-1)])]),_:1}),s[27]||(s[27]=a(" 榮譽推出",-1))])])}const I=l(c,[["render",g]]);export{R as __pageData,I as default};
